import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import '../styles/dialogues.css';

const Dialogues = () => {
  const { theme } = useParams();
  const navigate = useNavigate();
  const { currentLanguage } = useLanguage();
  const [dialogue, setDialogue] = useState([]);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [availableThemes, setAvailableThemes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [volume, setVolume] = useState(1);
  const [showTranslations, setShowTranslations] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const audioRef = useRef(null);
  const progressIntervalRef = useRef(null);
  const dialogueContainerRef = useRef(null);

  // Função para carregar temas disponíveis
  const loadAvailableThemes = async () => {
    try {
      const response = await fetch('/data/data.json');
      if (response.ok) {
        const data = await response.json();
        if (data.themes) {
          setAvailableThemes(data.themes);
          return;
        }
      }
    } catch (error) {
      console.warn('Erro ao carregar data.json:', error);
    }

    // Fallback para temas básicos
    setAvailableThemes([
      {
        id: 'daily_life',
        name: 'Daily Life',
        topics: [
          { id: 'morning_routine', name: 'Morning Routine' },
          { id: 'evening_plans', name: 'Evening Plans' }
        ]
      }
    ]);
  };

  // Função para carregar arquivo de diálogo
  const loadDialogueTxt = async (dialogueId, language = 'en') => {
    try {
      const response = await fetch(`/dialogues/${language}/${dialogueId}.txt`);
      if (!response.ok) {
        // Fallback para inglês se o idioma não existir
        if (language !== 'en') {
          return await loadDialogueTxt(dialogueId, 'en');
        }
        throw new Error(`Arquivo não encontrado: ${dialogueId}`);
      }
      const content = await response.text();
      return parseDialogueTxt(content);
    } catch (error) {
      console.error('Erro ao carregar diálogo:', error);
      return null;
    }
  };

  // Função para processar conteúdo do arquivo de texto
  const parseDialogueTxt = (content) => {
    const lines = content.split('\n').filter(line => line.trim());
    const dialogue = {
      title: '',
      lines: []
    };

    let currentLine = null;

    for (const line of lines) {
      if (line.startsWith('title:')) {
        dialogue.title = line.replace('title:', '').trim();
      }
      else if (line.startsWith('speaker:')) {
        if (currentLine && currentLine.speaker && currentLine.text) {
          dialogue.lines.push(currentLine);
        }
        currentLine = {
          speaker: line.replace('speaker:', '').trim(),
          text: '',
          translations: {}
        };
      }
      else if (line.startsWith('text:')) {
        if (currentLine) {
          currentLine.text = line.replace('text:', '').trim();
        }
      }
      else if (line.includes(':') && currentLine && !line.startsWith('title:') && !line.startsWith('speaker:') && !line.startsWith('text:')) {
        const colonIndex = line.indexOf(':');
        const lang = line.substring(0, colonIndex).trim();
        const translation = line.substring(colonIndex + 1).trim();
        currentLine.translations[lang] = translation;
      }
    }

    // Adicionar última linha
    if (currentLine && currentLine.speaker && currentLine.text) {
      dialogue.lines.push(currentLine);
    }

    return dialogue;
  };

  // Carregar diálogo específico
  const loadDialogue = async (themeName) => {
    try {
      setLoading(true);
      setError(null);

      let response;
      try {
        response = await fetch(`/dialogues/${currentLanguage}/${themeName}.txt`);
        if (!response.ok) throw new Error('Arquivo não encontrado');
      } catch {
        // Fallback para português
        response = await fetch(`/dialogues/pt/${themeName}.txt`);
        if (!response.ok) throw new Error('Arquivo não encontrado em nenhum idioma');
      }

      const text = await response.text();
      const parsedDialogue = parseDialogue(text);
      setDialogue(parsedDialogue);
      setCurrentPhraseIndex(0);
    } catch (error) {
      console.error('Erro ao carregar diálogo:', error);
      setError('Erro ao carregar o diálogo');
    } finally {
      setLoading(false);
    }
  };

  // Processar texto do diálogo
  const parseDialogue = (text) => {
    const lines = text.split('\n').filter(line => line.trim());
    return lines.map((line, index) => ({
      id: index,
      text: line.trim(),
      audioPath: `/audio/${currentLanguage}/${theme}/line_${index}.mp3`
    }));
  };

  // Reproduzir áudio
  const playAudio = (audioPath) => {
    if (audioRef.current) {
      audioRef.current.src = audioPath;
      audioRef.current.volume = volume;
      audioRef.current.play().catch(error => {
        console.error('Erro ao reproduzir áudio:', error);
      });
    }
  };

  // Reproduzir diálogo completo
  const playDialogue = () => {
    if (dialogue.length > 0) {
      setIsPlaying(true);
      setIsPaused(false);
      playCurrentPhrase();
      startProgressTracking();
    }
  };

  // Pausar diálogo
  const pauseDialogue = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setIsPlaying(false);
      setIsPaused(true);
      stopProgressTracking();
    }
  };

  // Parar diálogo
  const stopDialogue = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(0);
    setProgress(0);
    setCurrentTime(0);
    stopProgressTracking();
    removeAllHighlights();
  };

  // Reproduzir frase atual
  const playCurrentPhrase = () => {
    if (dialogue[currentPhraseIndex]) {
      playAudio(dialogue[currentPhraseIndex].audioPath);
      highlightCurrentPhrase();
    }
  };

  // Destacar frase atual
  const highlightCurrentPhrase = () => {
    removeAllHighlights();
    const messageElements = document.querySelectorAll('.message');
    if (messageElements[currentPhraseIndex]) {
      messageElements[currentPhraseIndex].classList.add('highlighted');
    }
  };

  // Remover todos os destaques
  const removeAllHighlights = () => {
    const messageElements = document.querySelectorAll('.message');
    messageElements.forEach(el => el.classList.remove('highlighted'));
  };

  // Iniciar rastreamento de progresso
  const startProgressTracking = () => {
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }

    progressIntervalRef.current = setInterval(() => {
      if (audioRef.current && !audioRef.current.paused) {
        const current = audioRef.current.currentTime;
        const total = audioRef.current.duration || 0;

        setCurrentTime(current);
        setTotalTime(total);

        if (total > 0) {
          setProgress((current / total) * 100);
        }
      }
    }, 100);
  };

  // Parar rastreamento de progresso
  const stopProgressTracking = () => {
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
  };

  // Navegar entre frases
  const nextPhrase = () => {
    if (currentPhraseIndex < dialogue.length - 1) {
      setCurrentPhraseIndex(currentPhraseIndex + 1);
    }
  };

  const prevPhrase = () => {
    if (currentPhraseIndex > 0) {
      setCurrentPhraseIndex(currentPhraseIndex - 1);
    }
  };

  // Controles do media player
  const toggleTranslations = () => {
    setShowTranslations(!showTranslations);
  };

  const toggleFullscreen = () => {
    if (dialogueContainerRef.current) {
      if (!isFullscreen) {
        dialogueContainerRef.current.classList.add('mobile-fullscreen');
      } else {
        dialogueContainerRef.current.classList.remove('mobile-fullscreen');
      }
      setIsFullscreen(!isFullscreen);
    }
  };

  const handleVolumeChange = (newVolume) => {
    setVolume(newVolume);
    if (audioRef.current) {
      audioRef.current.volume = newVolume;
    }
  };

  const formatTime = (seconds) => {
    if (isNaN(seconds)) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleProgressClick = (e) => {
    if (audioRef.current && audioRef.current.duration) {
      const rect = e.currentTarget.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const width = rect.width;
      const percentage = clickX / width;
      const newTime = percentage * audioRef.current.duration;

      audioRef.current.currentTime = newTime;
      setProgress(percentage * 100);
      setCurrentTime(newTime);
    }
  };

  // Event listeners para áudio
  useEffect(() => {
    const audio = audioRef.current;
    if (audio) {
      const handleEnded = () => {
        if (currentPhraseIndex < dialogue.length - 1) {
          setCurrentPhraseIndex(prev => prev + 1);
        } else {
          stopDialogue();
        }
      };

      const handleLoadedMetadata = () => {
        setTotalTime(audio.duration || 0);
      };

      audio.addEventListener('ended', handleEnded);
      audio.addEventListener('loadedmetadata', handleLoadedMetadata);

      return () => {
        audio.removeEventListener('ended', handleEnded);
        audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
      };
    }
  }, [currentPhraseIndex, dialogue.length]);

  // Auto-play próxima frase
  useEffect(() => {
    if (isPlaying && !isPaused) {
      playCurrentPhrase();
    }
  }, [currentPhraseIndex]);

  // Effects
  useEffect(() => {
    loadAvailableThemes();
  }, []);

  useEffect(() => {
    if (theme) {
      loadDialogue(theme);
    }
  }, [theme, currentLanguage]);

  // Cleanup
  useEffect(() => {
    return () => {
      stopProgressTracking();
    };
  }, []);

  // Renderização
  if (!theme) {
    return (
      <div className="content-below-navbar">
        <div className="page-title-container">
          <h1 className="page-title">Diálogos</h1>
        </div>

        <div className="container">
          <h2 className="section-title">Escolha Seu Próximo Tema:</h2>

          <div className="theme-grid">
            {availableThemes.map((themeGroup, index) => (
              <div key={index} className="theme-card">
                <h3>{themeGroup.title}</h3>
                <ul>
                  {themeGroup.topics.map(topic => (
                    <li 
                      key={topic.id}
                      onClick={() => navigate(`/dialogues/${topic.id}`)}
                    >
                      {topic.name}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="dialogues-container">
        <div className="loading">Carregando diálogo...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="dialogues-container">
        <div className="error">{error}</div>
        <button onClick={() => navigate('/dialogues')}>Voltar aos Temas</button>
      </div>
    );
  }

  return (
    <div className="content-below-navbar">
      <div className="page-title-container">
        <h1 className="page-title">Diálogos</h1>
      </div>

      <div className="container">
        <div className="dialogue-container" ref={dialogueContainerRef}>
          <h2 className="dialogue-title">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <span>{theme.replace('_', ' ')}</span>
          </h2>

          <div id="dialogue-content">
            {dialogue.map((phrase, index) => (
              <div 
                key={index} 
                className={`message ${index % 2 === 0 ? 'user' : 'other'}`}
                onClick={() => {
                  setCurrentPhraseIndex(index);
                  playCurrentPhrase();
                }}
              >
                {phrase.text}
                {showTranslations && (
                  <div className="translation">
                    {phrase.translation || 'Tradução não disponível'}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="media-player">
            <div className="player-controls">
              <button 
                className="player-btn" 
                id="play-btn"
                onClick={playDialogue}
                style={{ display: isPlaying ? 'none' : 'inline-flex' }}
              >
                <i className="fas fa-play"></i>
              </button>

              <button 
                className="player-btn" 
                id="pause-btn"
                onClick={pauseDialogue}
                style={{ display: isPlaying ? 'inline-flex' : 'none' }}
              >
                <i className="fas fa-pause"></i>
              </button>

              <button className="player-btn" id="stop-btn" onClick={stopDialogue}>
                <i className="fas fa-stop"></i>
              </button>

              <button 
                className={`player-btn ${showTranslations ? 'active' : ''}`} 
                onClick={toggleTranslations}
              >
                <i className="fas fa-language"></i>
              </button>

              <button 
                className={`player-btn ${isFullscreen ? 'active' : ''}`} 
                onClick={toggleFullscreen}
              >
                <i className={`fas ${isFullscreen ? 'fa-compress' : 'fa-expand'}`}></i>
              </button>

              <div className="volume-control">
                <button className="volume-btn">
                  <i className="fas fa-volume-up"></i>
                </button>
                <input 
                  type="range" 
                  id="volume-slider" 
                  min="0" 
                  max="1" 
                  step="0.1" 
                  value={volume}
                  onChange={(e) => handleVolumeChange(parseFloat(e.target.value))}
                />
              </div>
            </div>

            <div className="progress-container">
              <div 
                className="progress-bar" 
                onClick={handleProgressClick}
                style={{ '--progress': `${progress}%` }}
              ></div>
              <div className="time-display">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(totalTime)}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="text-center">
          <button 
            onClick={() => navigate('/dialogues')}
            className="cta-button"
          >
            ← Voltar aos Temas
          </button>
        </div>
      </div>

      <audio ref={audioRef} />
    </div>
  );
};

export default Dialogues;
